#[state]
enum ReviewState { Draft, Published }

#[machine]
struct Post<ReviewState> {
    title: String,
}

#[transition]
impl Post<Draft> {
    fn publish(self) -> Post<Published> {
        self.transition()
    }
}

#[state]
enum ReviewState {
    Draft,
    InReview(ReviewData),
    Published,
}

struct ReviewData {
    reviewer: String,
    notes: Vec<String>,
}

#[transition]
impl Post<Draft> {
    fn submit_for_review(self, reviewer: String) -> Post<InReview> {
        self.transition_with(ReviewData {
            reviewer,
            notes: vec![],
        })
    }
}

#[validators(TaskMachine)]
impl DbRow {
    fn is_draft(&self) -> statum::Result<()> {
        match self.state {
            Status::Draft => Ok(()),
            _ => Err(statum::Error::InvalidState),
        }
    }
}

#[nestum]
enum DocumentsEvent {
    Update(Document),
    Delete(String),
}

#[nestum]
enum Event {
    Documents(DocumentsEvent),
}

nested! {
    match event {
        Event::Documents::Update(doc) => {
            let _ = doc.id;
        }
        Event::Documents::Delete(id) => {
            let _ = id;
        }
    }
}

